INSERT INTO `projects` (`id`,`code`,`name`,`description`,`color`,`icon`,`owner_id`,`issue_counter`,`version`,`archived_at`,`created_at`,`updated_at`) VALUES
(1,'VOCAB','Ứng dụng học từ vựng tiếng Anh','Ứng dụng di động học từ vựng bằng flashcard, luyện phát âm, ôn tập ngắt quãng và bài kiểm tra theo cấp độ A1–C1.','#4f46e5','bi-translate',2,20,1,NULL,'2026-06-01 02:00:00','2026-06-01 02:00:00'),
(2,'PAY','Cổng thanh toán nội bộ','Cổng thanh toán nội bộ dùng giao dịch mô phỏng: tạo giao dịch, đối soát cuối ngày, hoàn tiền và theo dõi trạng thái. Toàn bộ là dữ liệu giả.','#0d9488','bi-credit-card',3,20,1,NULL,'2026-06-01 03:00:00','2026-06-01 03:00:00'),
(3,'IOT','Hệ thống giám sát nhà thông minh','Giám sát cảm biến nhiệt độ, độ ẩm, khói và điều khiển thiết bị trong nhà, kèm lịch bật/tắt và cảnh báo. Thiết bị là mô phỏng.','#ea580c','bi-house-gear',2,20,1,NULL,'2026-06-01 04:00:00','2026-06-01 04:00:00'),
(4,'HEALTH','Ứng dụng đặt lịch khám trực tuyến','Ứng dụng đặt lịch khám với bác sĩ: chọn chuyên khoa, khung giờ, nhận nhắc lịch và thông báo thay đổi. Dữ liệu bệnh nhân là giả.','#db2777','bi-heart-pulse',3,20,1,NULL,'2026-06-01 05:00:00','2026-06-01 05:00:00'),
(5,'EDU','Nền tảng học và thi trực tuyến','Nền tảng quản lý khóa học, bài giảng video và bài kiểm tra trực tuyến có giới hạn thời gian, chấm điểm tự động và tự nộp bài.','#2563eb','bi-mortarboard',2,20,1,NULL,'2026-06-01 06:00:00','2026-06-01 06:00:00'),
(6,'SHOP','Website bán thiết bị công nghệ','Website bán điện thoại, laptop, phụ kiện: danh mục sản phẩm, giỏ hàng, mã khuyến mãi và quản lý tồn kho theo kho.','#7c3aed','bi-bag',3,20,1,NULL,'2026-06-01 07:00:00','2026-06-01 07:00:00'),
(7,'FOOD','Ứng dụng đặt đồ ăn','Ứng dụng đặt món từ nhà hàng đối tác: thực đơn, giỏ món, theo dõi giao hàng và tính phí giao theo khoảng cách.','#dc2626','bi-bag-heart',2,20,1,NULL,'2026-06-01 08:00:00','2026-06-01 08:00:00'),
(8,'TOUR','Website đặt tour du lịch','Website đặt tour trong nước: danh sách tour, lịch khởi hành, số chỗ còn lại, đặt chỗ nhiều hành khách và thanh toán cọc.','#0891b2','bi-airplane',3,20,1,NULL,'2026-06-01 09:00:00','2026-06-01 09:00:00'),
(9,'AIHELP','Trợ lý AI hỗ trợ sinh viên','Trợ lý hội thoại giúp sinh viên tra cứu quy chế, tìm tài liệu học tập và nhắc lịch. Mô hình AI được thay bằng dịch vụ giả lập trong dữ liệu mẫu.','#9333ea','bi-robot',2,20,1,NULL,'2026-06-01 10:00:00','2026-06-01 10:00:00'),
(10,'FACE','Hệ thống điểm danh bằng nhận diện khuôn mặt','Hệ thống điểm danh lớp học bằng ảnh khuôn mặt: ghi nhận, báo cáo chuyên cần. Ảnh và mô hình nhận diện trong dữ liệu mẫu là giả lập.','#0f766e','bi-person-bounding-box',3,20,1,NULL,'2026-06-01 11:00:00','2026-06-01 11:00:00'),
(11,'JOB','Cổng tuyển dụng và tìm việc','Cổng đăng tin tuyển dụng, tìm việc, tải CV và ứng tuyển. Doanh nghiệp quản lý hồ sơ ứng viên theo từng tin tuyển dụng.','#ca8a04','bi-briefcase',2,20,1,NULL,'2026-06-01 12:00:00','2026-06-01 12:00:00'),
(12,'STOCK','Hệ thống quản lý kho hàng','Quản lý nhập, xuất, điều chuyển giữa các kho và kiểm kê định kỳ; theo dõi tồn kho theo mã hàng và vị trí.','#4d7c0f','bi-box-seam',3,20,1,NULL,'2026-06-01 13:00:00','2026-06-01 13:00:00'),
(13,'EVENT','Nền tảng quản lý sự kiện','Nền tảng tạo sự kiện, đăng ký tham dự, phát vé QR và check-in tại cổng bằng ứng dụng quét mã.','#c026d3','bi-ticket-perforated',2,20,1,NULL,'2026-06-01 14:00:00','2026-06-01 14:00:00'),
(14,'MONEY','Ứng dụng quản lý chi tiêu cá nhân','Ghi chép thu chi, đặt ngân sách theo danh mục và xem báo cáo theo tháng; có cảnh báo khi chi vượt ngân sách.','#16a34a','bi-wallet2',3,20,1,NULL,'2026-06-01 15:00:00','2026-06-01 15:00:00'),
(15,'GREEN','Ứng dụng thu gom và tái chế rác','Ứng dụng đặt lịch thu gom rác tái chế tại nhà, theo dõi trạng thái thu gom và tích điểm thưởng đổi quà.','#15803d','bi-recycle',2,20,1,NULL,'2026-06-01 16:00:00','2026-06-01 16:00:00'),
(16,'CLOUD','Hệ thống lưu trữ và chia sẻ tài liệu','Lưu trữ tệp, chia sẻ theo quyền xem/sửa, quản lý phiên bản tệp và thùng rác. Phù hợp nhóm làm việc nhỏ.','#0369a1','bi-cloud-arrow-up',3,20,1,NULL,'2026-06-01 17:00:00','2026-06-01 17:00:00');
