INSERT INTO `issues` (`id`,`project_id`,`number`,`code`,`type`,`title`,`description`,`priority`,`severity`,`status`,`reporter_id`,`assignee_id`,`due_date`,`environment`,`steps_to_reproduce`,`expected_result`,`actual_result`,`fix_ref`,`fix_revision`,`commit_url`,`pr_url`,`version`,`created_at`,`updated_at`) VALUES
(1,1,1,'VOCAB-1','bug','Mất tiến độ học khi đổi thiết bị','Lỗi ghi nhận khi kiểm thử \"Ứng dụng học từ vựng tiếng Anh\": Máy B hiển thị tiến độ 0 thẻ, streak bị đặt lại.','urgent','blocker','verified',10,6,NULL,'Android 14 – Pixel 7, app 2.3.1','Đăng nhập tài khoản trên máy A, học 30 thẻ → đăng nhập cùng tài khoản trên máy B','Tiến độ 30 thẻ được đồng bộ sang máy B','Máy B hiển thị tiến độ 0 thẻ, streak bị đặt lại','https://github.com/releasehub-demo/vocab/pull/101',1,'https://github.com/releasehub-demo/vocab/commit/0f2f4ae','https://github.com/releasehub-demo/vocab/pull/101',4,'2026-06-01 02:00:00','2026-06-01 23:00:00'),
(2,1,2,'VOCAB-2','bug','Tính sai điểm bài kiểm tra cuối bài','Lỗi ghi nhận khi kiểm thử \"Ứng dụng học từ vựng tiếng Anh\": Điểm hiển thị 5/10 vì câu bỏ trống bị tính hai lần.','urgent','blocker','verified',10,7,NULL,'iOS 17.4 – iPhone 13, app 2.3.1','Làm bài 20 câu, đúng 15 câu → nộp bài','Điểm hiển thị 7,5/10','Điểm hiển thị 5/10 vì câu bỏ trống bị tính hai lần','https://github.com/releasehub-demo/vocab/pull/102',1,'https://github.com/releasehub-demo/vocab/commit/f5216fc','https://github.com/releasehub-demo/vocab/pull/102',4,'2026-06-01 11:00:00','2026-06-02 08:00:00'),
