(302,16,2,'CLOUD-2','bug','Tải lên tệp lớn thất bại và để lại tệp hỏng','Lỗi ghi nhận khi kiểm thử \"Hệ thống lưu trữ và chia sẻ tài liệu\": Tệp 1,2 GB hỏng xuất hiện trong thư mục.','urgent','blocker','reopened',10,6,'2026-12-07','Ứng dụng đồng bộ – Windows 11, bản 0.7.0','Tải lên tệp 2 GB, ngắt mạng ở 60%','Tải tiếp tục được hoặc dọn phần dở','Tệp 1,2 GB hỏng xuất hiện trong thư mục','https://github.com/releasehub-demo/cloud/pull/102',1,'https://github.com/releasehub-demo/cloud/commit/8843585','https://github.com/releasehub-demo/cloud/pull/102',4,'2026-06-04 14:00:00','2026-06-05 11:00:00'),
(303,16,3,'CLOUD-3','bug','Liên kết chia sẻ không hết hạn dù đã đặt thời hạn','Lỗi ghi nhận khi kiểm thử \"Hệ thống lưu trữ và chia sẻ tài liệu\": Liên kết vẫn mở sau 1 ngày.','high','critical','closed',10,9,NULL,'Web – Chrome 124 / Windows 11, PHP 8.2','Đặt hết hạn sau 1 giờ','Liên kết vô hiệu sau 1 giờ','Liên kết vẫn mở sau 1 ngày','https://github.com/releasehub-demo/cloud/pull/103',1,'https://github.com/releasehub-demo/cloud/commit/fa19771','https://github.com/releasehub-demo/cloud/pull/103',5,'2026-06-04 23:00:00','2026-06-06 03:00:00'),
(304,16,4,'CLOUD-4','bug','Khôi phục phiên bản cũ ghi đè phiên bản mới nhất mà không lưu lại','Lỗi ghi nhận khi kiểm thử \"Hệ thống lưu trữ và chia sẻ tài liệu\": Phiên bản 5 biến mất.','high','critical','reopened',10,6,'2026-12-11','Ứng dụng đồng bộ – Windows 11, bản 0.7.0','Khôi phục phiên bản 2 của tệp có 5 phiên bản','Phiên bản mới nhất được giữ trong lịch sử','Phiên bản 5 biến mất','https://github.com/releasehub-demo/cloud/pull/104',1,'https://github.com/releasehub-demo/cloud/commit/63369a1','https://github.com/releasehub-demo/cloud/pull/104',4,'2026-06-05 08:00:00','2026-06-06 05:00:00'),
(305,16,5,'CLOUD-5','bug','Đổi tên thư mục làm hỏng đường dẫn chia sẻ','Lỗi ghi nhận khi kiểm thử \"Hệ thống lưu trữ và chia sẻ tài liệu\": Liên kết báo 404.','high','major','closed',10,9,NULL,'Web – Chrome 124 / Windows 11, PHP 8.2','Đổi tên thư mục đang được chia sẻ','Liên kết vẫn hoạt động','Liên kết báo 404','https://github.com/releasehub-demo/cloud/pull/105',1,'https://github.com/releasehub-demo/cloud/commit/4b9fd4f','https://github.com/releasehub-demo/cloud/pull/105',5,'2026-06-05 17:00:00','2026-06-06 21:00:00'),
(306,16,6,'CLOUD-6','bug','Tìm kiếm tên tệp không hỗ trợ ký tự đặc biệt','Lỗi ghi nhận khi kiểm thử \"Hệ thống lưu trữ và chia sẻ tài liệu\": Không có kết quả.','medium','major','verified',10,6,NULL,'Ứng dụng đồng bộ – Windows 11, bản 0.7.0','Tìm \"Báo cáo (bản 2)\"','Tìm thấy tệp','Không có kết quả','https://github.com/releasehub-demo/cloud/pull/106',1,'https://github.com/releasehub-demo/cloud/commit/b4955ed','https://github.com/releasehub-demo/cloud/pull/106',4,'2026-06-06 02:00:00','2026-06-06 23:00:00'),
(307,16,7,'CLOUD-7','bug','Dung lượng đã dùng tính cả tệp trong thùng rác','Lỗi ghi nhận khi kiểm thử \"Hệ thống lưu trữ và chia sẻ tài liệu\": Giảm ngay nhưng cộng lại khi mở trang khác.','high','major','closed',10,9,NULL,'Web – Chrome 124 / Windows 11, PHP 8.2','Xóa tệp 100 MB','Dung lượng giảm sau khi xóa vĩnh viễn','Giảm ngay nhưng cộng lại khi mở trang khác','https://github.com/releasehub-demo/cloud/pull/107',1,'https://github.com/releasehub-demo/cloud/commit/13e3a08','https://github.com/releasehub-demo/cloud/pull/107',5,'2026-06-06 11:00:00','2026-06-07 15:00:00'),
(308,16,8,'CLOUD-8','bug','Thành viên bị gỡ khỏi nhóm vẫn truy cập được tệp','Lỗi ghi nhận khi kiểm thử \"Hệ thống lưu trữ và chia sẻ tài liệu\": Truy cập được tới khi đăng xuất.','medium','major','in_progress',10,6,'2026-12-19','Ứng dụng đồng bộ – Windows 11, bản 0.7.0','Gỡ thành viên khỏi nhóm','Mất quyền ngay','Truy cập được tới khi đăng xuất',NULL,0,NULL,NULL,2,'2026-06-06 20:00:00','2026-06-07 03:00:00'),
(309,16,9,'CLOUD-9','bug','Xem trước PDF không hiển thị tiếng Việt có dấu','Lỗi ghi nhận khi kiểm thử \"Hệ thống lưu trữ và chia sẻ tài liệu\": Ký tự vuông.','low','minor','verified',10,9,NULL,'Web – Chrome 124 / Windows 11, PHP 8.2','Xem trước PDF tiếng Việt','Hiển thị đúng dấu','Ký tự vuông','https://github.com/releasehub-demo/cloud/pull/109',1,'https://github.com/releasehub-demo/cloud/commit/a0577cc','https://github.com/releasehub-demo/cloud/pull/109',4,'2026-06-07 05:00:00','2026-06-08 02:00:00'),
(310,16,10,'CLOUD-10','bug','Sắp xếp theo ngày sửa đổi lệch múi giờ','Lỗi ghi nhận khi kiểm thử \"Hệ thống lưu trữ và chia sẻ tài liệu\": Sai thứ tự quanh nửa đêm.','medium','minor','open',10,NULL,'2026-10-20','Ứng dụng đồng bộ – Windows 11, bản 0.7.0','Sắp theo ngày sửa','Đúng thứ tự giờ địa phương','Sai thứ tự quanh nửa đêm',NULL,0,NULL,NULL,1,'2026-06-07 14:00:00','2026-06-07 14:00:00'),
(311,16,11,'CLOUD-11','bug','Kéo thả nhiều tệp chỉ tải tệp đầu','Lỗi ghi nhận khi kiểm thử \"Hệ thống lưu trữ và chia sẻ tài liệu\": Chỉ tải 1 tệp.','low','minor','reopened',10,9,'2026-12-25','Web – Chrome 124 / Windows 11, PHP 8.2','Kéo 5 tệp vào trang','Tải đủ 5 tệp','Chỉ tải 1 tệp','https://github.com/releasehub-demo/cloud/pull/1011',1,'https://github.com/releasehub-demo/cloud/commit/efe2e57','https://github.com/releasehub-demo/cloud/pull/1011',4,'2026-06-07 23:00:00','2026-06-08 20:00:00'),
